Definir Alfa aCursor$NOME$;
Definir Alfa aQuery$NOME$;
aQuery$NOME$ = "$QUERY$";
SQL_Criar(aCursor$NOME$);
SQL_UsarAbrangencia(aCursor$NOME$, 0);
SQL_UsarSQLSenior2(aCursor$NOME$, 0);
SQL_DefinirComando(aCursor$NOME$, aQuery$NOME$);
SQL_AbrirCursor(aCursor$NOME$);
Se(SQL_EOF(aCursor$NOME$) = 0){
  $END$
}
SQL_FecharCursor(aCursor$NOME$);
SQL_Destruir(aCursor$NOME$);

Definir Alfa aCursor$NOME$;
Definir Alfa aQuery$NOME$;
aQuery$NOME$ = "$QUERY$";
SQL_Criar(aCursor$NOME$);
SQL_UsarAbrangencia(aCursor$NOME$, 0);
SQL_UsarSQLSenior2(aCursor$NOME$, 0);
SQL_DefinirComando(aCursor$NOME$, aQuery$NOME$);
SQL_AbrirCursor(aCursor$NOME$);
Enquanto(SQL_EOF(aCursor$NOME$) = 0){
  $END$
  SQL_Proximo(aCursor$NOME$);
}
SQL_FecharCursor(aCursor$NOME$);
SQL_Destruir(aCursor$NOME$);

Definir Alfa aRecursos;
Definir Alfa aResponse;
aRecursos = "$RECURSO$";
aResponse = "{}";
Definir Funcao f001ValidarPermissaoUsuario();
f001ValidarPermissaoUsuario();
Se(nHasRecurso = 0){
  addKeyAndIntegerValueInJSON(aResponse, "status", 403, aResponse);
  Web_HTML = aResponse;
  Cancel;
}
$END$

lLogAuditoria.Adicionar();
lLogAuditoria.funcionalidade = "$FUNC$";
lLogAuditoria.descricaoRegistro = "$DESC$";
lLogAuditoria.operacao = "$OPER$";
lLogAuditoria.codigoRegistro = $CODIGO$;
lLogAuditoria.tabela = "$TABELA$";
lLogAuditoria.Gravar();

lLogItens.Adicionar();
lLogItens.campo = "$CAMPO$";
lLogItens.campoTabela = "$CAMPOTAB$";
lLogItens.novoValor = $VALOR$;
lLogItens.Gravar();$END$

Definir Alfa aResponse;
aResponse = "{}";
addKeyAndStringValueInJSON(aResponse, "$CHAVE$", $VALOR$, aResponse);
Web_HTML = aResponse;$END$

Definir Numero nPageSize;
Definir Numero nPageIndex;
Definir Alfa aSortField;
Definir Alfa aSortOrder;
Definir Numero nPageOffset;
WCheckValInteger("pageSize", "", nPageSize, "N", 9999999);
WCheckValInteger("pageIndex", "", nPageIndex, "N", 9999999);
WCheckValString("sortField", "", aSortField, "S", 9999999);
WCheckValString("sortOrder", "", aSortOrder, "S", 9999999);
nPageOffset = nPageIndex * nPageSize;$END$
